@Test
@WithMockUser
void shouldRecordWeight() throws Exception {
    mockMvc.perform(post("/owners/1/pets/1/weight")
        .contentType(MediaType.APPLICATION_JSON)
        .content("{\"weightKg\":5.2,\"recordDate\":\"2023-05-15\"}"))
