@Test
@WithMockUser
void shouldGetWeightHistory() throws Exception {
    List<WeightRecord> records = List.of(
        new WeightRecord(1L, 5.2, LocalDate.now().minusDays(1)),
        new WeightRecord(1L, 5.0, LocalDate.now())
    );

    when(weightRecordRepository.findByPetIdOrderByRecordDateDesc(1L))
        .thenReturn(records);

    mockMvc.perform(get("/owners/1/pets/1/weight/history"))
        .andExpect(status().isOk())
        .andExpect(jsonPath("$[0].weightKg").value(5.0))
        .andExpect(jsonPath("$[1].weightKg").value(5.2));
}


### 4. Implement controller methods

**OwnerController.java** (add these methods)
java
@PostMapping("/owners/{ownerId}/pets/{petId}/weight")
public ResponseEntity<Void> recordWeight(
    @PathVariable("ownerId") int ownerId,
    @PathVariable("petId") long petId,
    @Valid @RequestBody WeightRecord weightRecord) {

    Pet pet = petRepository.findById(petId);
    if (pet == null || pet.getOwner().getId() != ownerId) {
        return ResponseEntity.notFound().build();
    }

    weightRecord.setPetId(petId);
    weightRecordRepository.save(weightRecord);
    return ResponseEntity.status(HttpStatus.CREATED).build();
}

@GetMapping("/owners/{ownerId}/pets/{petId}/weight/history")
public ResponseEntity<List<WeightRecord>> getWeightHistory(
    @PathVariable("ownerId") int ownerId,
    @PathVariable("petId") long petId) {

    Pet pet = petRepository.findById(petId);
    if (pet == null || pet.getOwner().getId() != ownerId) {
        return ResponseEntity.notFound().build();
    }

    return ResponseEntity.ok(
        weightRecordRepository.findByPetIdOrderByRecordDateDesc(petId)
    );
}


