```typescript
import { Mcp, Tool } from '@modelcontextprotocol/sdk';
import * as sqlite3 from 'sqlite3';
import { open } from 'sqlite';
import * as fs from 'fs';
import * as path from 'path';
import * as glob from 'glob';
import * as frontMatter from 'front-matter';

// Open the SQLite database
let db;

async function initializeDatabase() {
  db = await open({
    filename: './markdown.db',
    driver: sqlite3.Database
  });

  // Create the FTS5 table if it doesn't exist
  await db.exec(`
    CREATE VIRTUAL TABLE IF NOT EXISTS documents USING fts5(
      path,
      title,
      tags,
      content
    );
  `);
}

// Tool: index_markdown
const indexMarkdown: Tool = {
  name: 'index_markdown',
  description: 'Index markdown files in a directory',
  parameters: {
    type: 'object',
    properties: {
      dir_path: { type: 'string', description: 'Path to the directory containing markdown files' }
    },
    required: ['dir_path']
  },
  execute: async (params: { dir_path: string }) => {
    const { dir_path } = params;
    if (!fs.existsSync(dir_path)) {
      throw new Error(`Directory not found: ${dir_path}`);
    }

    const files = glob.sync(path.join(dir_path, '**/*.md'));
    for (const file of files) {
      const content = fs.readFileSync(file, 'utf8');
      const parsed = frontMatter<{ tags?: string[] }>(content);
      const attributes = parsed.attributes;
      const body = parsed.body;

      // Extract the first heading (if any)
      let title = '';
      const headingMatch = body.match(/^#\s+(.*)$/m);
      if (headingMatch) {
        title = headingMatch[1];
      }

      // Insert into the database
      await db.run(`
        INSERT INTO documents (path, title, tags, content)
        VALUES (?, ?, ?, ?)
      `, [file, title, attributes?.tags?.join(', ') || '', body]);
    }

    return { message: `Indexed ${files.length} files` };
  }
};

// Tool: search_documents
const searchDocuments: Tool = {
  name: 'search_documents',
  description: 'Search documents using a query',
  parameters: {
    type: 'object',
    properties: {
      query: { type: 'string', description: 'Search query' }
    },
    required: ['query']
  },
  execute: async (params: { query: string }) => {
    const { query } = params;
    const results = await db.all(`
      SELECT rowid as id, path, title, snippet(documents, 2, '<b>', '</b>', '...', 64) as snippet
      FROM documents
      WHERE documents MATCH ?
    `, [query]);

    return results;
  }
};

// Tool: read_document
const readDocument: Tool = {
  name: 'read_document',
  description: 'Read a document by id',
  parameters: {
    type: 'object',
    properties: {
      doc_id: { type: 'number', description: 'Document ID' }
    },
    required: ['doc_id']
  },
  execute: async (params: { doc_id: number }) => {
    const { doc_id } = params;
    const result = await db.get(`
      SELECT content
      FROM documents
      WHERE rowid = ?
    `, [doc_id]);

    if (!result) {
      throw new Error(`Document with id ${doc_id} not found`);
    }

    return { content: result.content };
  }
};

// Main function to start the MCP server
async function main() {
  await initializeDatabase();

  const mcp = new Mcp();
  mcp.registerTool(indexMarkdown);
  mcp.registerTool(searchDocuments);
  mcp.registerTool(readDocument);

  mcp.start();
}

main().catch(console.error);
```

