     @PostMapping("/owners/{ownerId}/pets/{petId}/weight")
     public ResponseEntity<?> recordWeight(
         @PathVariable("ownerId") int ownerId,
         @PathVariable("petId") int petId,
         @RequestBody WeightRequest weightRequest) {

         Owner owner = this.owners.findById(ownerId);
         if (owner == null) {
             return ResponseEntity.notFound().build();
         }
         Pet pet = this.pets.findById(petId);
         if (pet == null || pet.getOwner().getId() != ownerId) {
             return ResponseEntity.notFound().build();
         }

         if (weightRequest.getWeightKg() == null || weightRequest.getRecordDate() == null) {
             return ResponseEntity.badRequest().body("Missing required fields");
         }

         WeightRecord record = new WeightRecord();
         record.setPetId((long)petId);
         record.setWeightKg(weightRequest.getWeightKg());
         record.setRecordDate(weightRequest.getRecordDate());
         weightRecordRepository.save(record);

         return ResponseEntity.status(HttpStatus.CREATED).body(record);
     }

     @GetMapping("/owners/{ownerId}/pets/{petId}/weight/history")
     public ResponseEntity<?> getWeightHistory(
         @PathVariable("ownerId") int ownerId,
         @PathVariable("petId") int petId) {

         Owner owner = this.owners.findById(ownerId);
         if (owner == null) {
             return ResponseEntity.notFound().build();
         }
         Pet pet = this.pets.findById(petId);
         if (pet == null || pet.getOwner().getId() != ownerId) {
             return ResponseEntity.notFound().build();
         }

         List<WeightRecord> history = weightRecordRepository.findByPetIdOrderByRecordDateDesc((long)petId);
         return ResponseEntity.ok(history);
     }

