import { McpServer, Tool } from '@modelcontextprotocol/sdk';
import { open } from 'sqlite';
import sqlite3 from 'sqlite3';
import * as fs from 'fs';
import * as path from 'path';
import matter from 'gray-matter';
import { promisify } from 'util';

const readdir = promisify(fs.readdir);
const readFile = promisify(fs.readFile);
const exists = promisify(fs.exists);

// Database setup
const DB_FILE = 'markdown-kb.db';

async function initializeDb() {
  const db = await open({
    filename: DB_FILE,
    driver: sqlite3.Database
  });

  // Create the FTS5 table if it doesn't exist
  await db.exec(`
    CREATE VIRTUAL TABLE IF NOT EXISTS documents USING fts5(
      path UNINDEXED,
      title,
      tags,
      content
    );
  `);

  return db;
}

// Tool: index_markdown
export async function indexMarkdown(dirPath: string, db: any) {
  // Check if directory exists
  if (!await exists(dirPath)) {
    throw new Error(`Directory not found: ${dirPath}`);
  }

  // Read all markdown files in the directory
  const files = await readdir(dirPath);
  const mdFiles = files.filter(file => file.endsWith('.md'));

  for (const file of mdFiles) {
    const filePath = path.join(dirPath, file);
    const content = await readFile(filePath, 'utf8');
    const { data: frontMatter } = matter(content);

    // Extract title: first h1 in the content or use the file name without extension
    let title = frontMatter.title || '';
    if (!title) {
      // Look for the first # heading in the entire content (might be in the front-matter? but matter removes the front-matter from the content? Actually, the matter function returns the content without the front-matter. So we cannot find the heading in the front-matter. We are only looking in the markdown part.
      // But note: the entire content is stored, so we can search the entire string? We are using the entire content for the FTS, but for the title we are only looking in the markdown part (after front-matter). That's acceptable.
      const headingMatch = content.match(/^#\s+(.+)$/m);
      if (headingMatch) {
        title = headingMatch[1].trim();
      } else {
        title = path.basename(file, '.md');
      }
    }

    const tags = frontMatter.tags || [];
    // Convert tags to a string for FTS5: we'll store as comma separated
    const tagsString = Array.isArray(tags) ? tags.join(', ') : tags;

    // Insert or replace by path
    await db.run(`
      INSERT INTO documents (path, title, tags, content)
      VALUES (?, ?, ?, ?)
      ON CONFLICT(path) DO UPDATE SET
        title = excluded.title,
        tags = excluded.tags,
        content = excluded.content;
    `, [filePath, title, tagsString, content]);
  }

  return { success: true, indexed: mdFiles.length };
}

// Tool: search_documents
export async function searchDocuments(query: string, db: any) {
  if (!query) {
    return [];
  }

  // We use the FTS5 search. Note: the query must be valid FTS5 syntax.
  const results = await db.all(`
    SELECT rowid as id, title, snippet(documents, 2, '<b>', '</b>', '...', 64) AS snippet
    FROM documents
    WHERE documents MATCH ?
    ORDER BY rank
  `, [query]);

  return results;
}

// Tool: read_document
export async function readDocument(docId: number, db: any) {
  const result = await db.get(`
    SELECT content FROM documents WHERE rowid = ?
  `, [docId]);

  if (!result) {
    throw new Error(`Document with id ${docId} not found`);
  }

  return result.content;
}

async function main() {
  const db = await initializeDb();

  // Create MCP server
  const server = new McpServer();

  // Register tools
  server.registerTool(new Tool(
    'index_markdown',
    'Index markdown files from a directory',
    { dir_path: { type: 'string', description: 'Path to the directory containing markdown files' } },
    async (params: { dir_path: string }) => {
