```zig
const std = @import("std");
const JSC = @import("root").bun.JSC;
const JSGlobalObject = JSC.JSGlobalObject;
const JSValue = JSC.JSValue;
const CallFrame = JSC.CallFrame;
const bun = @import("root").bun;
const Output = bun.Output;
const Allocator = std.mem.Allocator;

const Algorithm = enum {
    murmur3,
    xxhash32,
    xxhash64,
    wyhash,

    pub fn fromString(str: []const u8) ?Algorithm {
        if (std.ascii.eqlIgnoreCase(str, "murmur3")) {
            return .murmur3;
        } else if (std.ascii.eqlIgnoreCase(str, "xxhash32")) {
            return .xxhash32;
        } else if (std.ascii.eqlIgnoreCase(str, "xxhash64")) {
            return .xxhash64;
        } else if (std.ascii.eqlIgnoreCase(str, "wyhash")) {
            return .wyhash;
        } else {
            return null;
        }
    }
};

pub const BunHash = struct {
    algorithm: Algorithm,
    state: State,
    allocator: Allocator,

    const State = union(Algorithm) {
        murmur3: std.hash.murmur.Murmur3_32,
        xxhash32: std.hash.XxHash32,
        xxhash64: std.hash.XxHash64,
        wyhash: std.hash.Wyhash,

        pub fn update(self: *State, data: []const u8) void {
            switch (self.*) {
                .murmur3 => |*s| s.update(data),
                .xxhash32 => |*s| s.update(data),
                .xxhash64 => |*s| s.update(data),
                .wyhash => |*s| s.update(data),
            }
        }

        pub fn final(self: *State) u64 {
            return switch (self.*) {
                .murmur3 => |s| s.final(),
                .xxhash32 => |s| s.final(),
                .xxhash64 => |s| s.final(),
                .wyhash => |s| s.final(),
            };
        }

        pub fn reset(self: *State) void {
            switch (self.*) {
                .murmur3 => |*s| s.reset(),
                .xxhash32 => |*s| s.reset(),
                .xxhash64 => |*s| s.reset(),
                .wyhash => |*s| s.reset(),
            }
        }
    };

    pub const js = JSC.Codegen.JSBunHash;

    pub fn constructor(
        globalObject: *JSGlobalObject,
        callFrame: *CallFrame,
    ) bun.JSError!*BunHash {
        const args = callFrame.arguments(1);
        if (args.len < 1) {
            return globalObject.throw("BunHash requires an algorithm name", .{});
        }

        const algorithm_str = args.ptr[0].toSlice(globalObject, bun.default_allocator);
        defer algorithm_str.deinit();
        const algorithm_name = algorithm_str.slice();

        const algorithm = Algorithm.fromString(algorithm_name) orelse {
            return globalObject.throw("Invalid algorithm. Supported: murmur3, xxhash32, xxhash64, wyhash", .{});
        };

        var this = bun.new(BunHash, .{
            .algorithm = algorithm,
            .state = switch (algorithm) {
                .murmur3 => State{ .murmur3 = std.hash.murmur.Murmur3_32.init(0) },
                .xxhash32 => State{ .xxhash32 = std.hash.XxHash32.init(0) },
                .xxhash64 => State{ .xxhash64 = std.hash.XxHash64.init(0) },
                .wyhash => State{ .wyhash = std.hash.Wyhash.init(0) },
            },
            .allocator = bun.default_allocator,
        });

        return this;
    }

    pub fn hash(
        this: *BunHash,
        globalObject: *JSGlobalObject,
        callFrame: *CallFrame,
    ) bun.JSError!JSValue {
        const args = callFrame.arguments(1);
        if (args.len < 1) {
            return globalObject.throw("Expected data to hash", .{});
        }

        const value = args.ptr[0];
        var input_slice = JSC.Node.SliceOrBuffer.fromJS(globalObject, bun.default_allocator, value, null) orelse {
            return globalObject.throw("Expected data to be a string or Uint8Array", .{});
        };
        defer input_slice.deinit();

        this.state.update(input_slice.slice());

        return this;
    }

    pub fn digest(
        this: *BunHash,
        globalObject: *JSGlobalObject,
        _: *CallFrame,
    ) bun.JSError!JSValue {
        const hash_value = this.state.final();
        // We need to format the hash as a hex string.
        // The hash_value is u64, but for murmur3 and xxhash32 we only use the lower 32 bits.
        // We'll format as 16 hex digits (64 bits) for all, but for 32-bit hashes we'll zero-pad the upper 32 bits?
        // Actually, we can just format the entire u64. For 32-bit hashes, the upper 32 bits are zero? Not necessarily for wyhash and xxhash64.

        // Instead, we'll handle each algorithm differently?
        // But the `final` method returns u64 for all. For 32-bit hashes, we should only return 8 hex digits.

        // Let's adjust by algorithm:
        var hex_string: []u8 = undefined;
        switch (this.algorithm) {
            .murmur3, .xxhash32 => {
                // Format as 8 hex digits (32 bits)
                const n = @truncate(u32, hash_value);
                hex_string = bun.default_allocator.alloc(u8, 8) catch bun.outOfMemory();
                _ = std.fmt.bufPrint(hex_string, "{x:0>8}", .{n}) catch unreachable;
            },
            .xxhash64, .wyhash => {
                // Format as 16 hex digits (64 bits)
                hex_string = bun.default_allocator.alloc(u8, 16) catch bun.outOfMemory();
                _ = std.fmt.bufPrint(hex_string, "{x:0>16}", .{hash_value}) catch unreachable;
            },
        }

        defer bun.default_allocator.free(hex_string);
        return JSValue.createString(globalObject, hex_string, true);
    }

    pub fn getAlgorithm(
        this: *BunHash,
        globalObject: *JSGlobalObject,
    ) bun.JSError!JSValue {
        const name = switch (this.algorithm) {
            .murmur3 => "murmur3",
            .xxhash32 => "xxhash32",
            .xxhash64 => "xxhash64",
            .wyhash => "wyhash",
        };
        return JSValue.createString(globalObject, name, true);
    }

    pub fn deinit(this: *BunHash) void {
        // Currently, we don't have any heap-allocated state beyond the struct itself.
        // But we might in the future.
    }

    pub fn finalize(this: *BunHash) void {
        this.deinit();
        bun.destroy(this);
    }
};
```

Note: We are using `JSC.Node.SliceOrBuffer` to handle both strings and Uint8Arrays. This is a utility in Bun that we can use.

