{"task": "Create file: Examples/DCFValuation/DCFDemo.cpp

#include <ql/quantlib.hpp>
#include <iostream>

using namespace QuantLib;
using namespace std;

int main() {
    try {
        // Set evaluation date
        Date today(15, July, 2023);
        Settings::instance().evaluationDate() = today;

        // Create flat yield curve @ 5%
        double rate = 0.05;
        DayCounter dayCounter = Actual360();
        Compounding compounding = Continuous;
        Frequency frequency = Annual;
        boost::shared_ptr<YieldTermStructure> curve(
            new FlatForward(today, rate, dayCounter, compounding, frequency));

        // Create cash flow schedule: 5Y annual bond @ 6%
        Date issueDate = today;
        Date maturityDate = issueDate + Period(5, Years);
        Schedule schedule(issueDate, maturityDate, Period(Annual), TARGET(),
                          Unadjusted, Unadjusted, DateGeneration::Backward, false);
        vector<Rate> coupons(5, 0.06);
        Leg cashflows = FixedRateLeg(schedule)
            .withNotionals(100.0)
            .withCouponRates(coupons, dayCounter);

        // Calculate NPV
        double npv = CashFlows::npv(cashflows, *curve, false);
        cout << "Net Present Value: " << npv << endl;

        // Calculate duration/convexity
        double duration = CashFlows::duration(cashflows, *curve, Duration::Modified, false);
        double convexity = CashFlows::convexity(cashflows, *curve, false);
        cout << "Modified Duration: " << duration << endl;
        cout << "Convexity: " << convexity << endl;

        // Sensitivity analysis (+100bps)
        double shift = 0.01;
        boost::shared_ptr<YieldTermStructure> shiftedCurve(
            new FlatForward(today, rate+shift, dayCounter, compounding, frequency));
        double npvShifted = CashFlows::npv(cashflows, *shiftedCurve, false);
        cout << "\nSensitivity Analysis (+100bps):" << endl;
        cout << "New NPV: " << npvShifted << endl;
        cout << "Delta: " << (npvShifted - npv) << endl;

        // Print discounted cash flows
        cout << "\nDiscounted Cash Flows:" << endl;
        for (Size i=0; i<cashflows.size(); i++) {
            Date paymentDate = cashflows[i]->date();
            double amount = cashflows[i]->amount();
            double discountFactor = curve->discount(paymentDate);
            cout << paymentDate << ": " << amount
                 << " | Discounted: " << amount * discountFactor
                 << " | DF: " << discountFactor << endl;
        }

        return 0;
    } catch (exception& e) {
        cerr << e.what() << endl;
        return 1;
    }
}"}

