I'll help you implement TCP metrics collection for Linkerd. Here's the solution:

go:file=viz/metrics-api/examples/tcp_metrics_demo.go
package main

import (
	"fmt"
	"net/http"
	"sync"
	"time"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promhttp"
)

var (
	tcpOpenTotal = prometheus.NewCounterVec(
		prometheus.CounterOpts{
			Name: "tcp_open_total",
			Help: "Total TCP connections opened",
		},
		[]string{"server", "client"},
	)

	tcpCloseTotal = prometheus.NewCounterVec(
		prometheus.CounterOpts{
			Name: "tcp_close_total",
			Help: "Total TCP connections closed",
		},
		[]string{"server", "client", "reason"},
	)

	tcpConnectionDurationMs = prometheus.NewHistogramVec(
		prometheus.HistogramOpts{
			Name:    "tcp_connection_duration_ms",
			Help:    "TCP connection duration in milliseconds",
			Buckets: []float64{10, 50, 100, 500, 1000, 5000},
		},
		[]string{"server", "client"},
	)

	tcpReadBytesTotal = prometheus.NewCounterVec(
		prometheus.CounterOpts{
			Name: "tcp_read_bytes_total",
			Help: "Total bytes read over TCP",
		},
		[]string{"server", "client"},
	)

	tcpWriteBytesTotal = prometheus.NewCounterVec(
		prometheus.CounterOpts{
			Name: "tcp_write_bytes_total",
			Help: "Total bytes written over TCP",
		},
		[]string{"server", "client"},
	)

	connectionMutex sync.Mutex
	activeConns     = make(map[string]time.Time)
)

func init() {
	prometheus.MustRegister(tcpOpenTotal)
	prometheus.MustRegister(tcpCloseTotal)
	prometheus.MustRegister(tcpConnectionDurationMs)
	prometheus.MustRegister(tcpReadBytesTotal)
	prometheus.MustRegister(tcpWriteBytesTotal)
}

func main() {
	// Start metrics HTTP server
	go func() {
		http.Handle("/metrics", promhttp.Handler())
		http.ListenAndServe(":8080", nil)
	}()

	// Simulate TCP connections
	for {
		time.Sleep(2 * time.Second)
		go simulateTCPConnection("web-server", "client-app")
		go simulateTCPConnection("db-service", "web-server")
	}
}

func simulateTCPConnection(server, client string) {
	// Record connection open
	connID := fmt.Sprintf("%s-%s-%d", server, client, time.Now().UnixNano())
	tcpOpenTotal.WithLabelValues(server, client).Inc()

	// Track connection start time
	start := time.Now()
	connectionMutex.Lock()
	activeConns[connID] = start
	connectionMutex.Unlock()

	// Simulate connection duration
	duration := time.Duration(100+rand.Intn(4900)) * time.Millisecond
	time.Sleep(duration)

	// Simulate data transfer
	readBytes := rand.Intn(10240)
	writeBytes := rand.Intn(10240)
	tcpReadBytesTotal.WithLabelValues(server, client).Add(float64(readBytes))
	tcpWriteBytesTotal.WithLabelValues(server, client).Add(float64(writeBytes))

	// Record connection close
	closeReason := "normal"
	if rand.Float32() < 0.1 {
		closeReason = "timeout"
	}
	tcpCloseTotal.WithLabelValues(server, client, closeReason).Inc()
	tcpConnectionDurationMs.WithLabelValues(server, client).Observe(float64(duration.Milliseconds()))

	// Cleanup
	connectionMutex.Lock()
	delete(activeConns, connID)
	connectionMutex.Unlock()
}


